// core/dsp-link, Digitakt II: the geometry of the frame tail and the reserved area. The numbers are the device file's
// ([digikit] dsp_tail_off, dsp_tail_words, dsp_area_bytes of devices/digitakt-ii.toml); build/gen/device-dt2.inc is generated by
// `patchkit gen`.
//
// The ColdFire sends 0xabc bytes per block and fills 0x802 of them with data (finding 23, S4b). The DSP's receive ring
// holds them as 32-bit words, two wire halfwords each, the first one in the low half (finding 31). The first whole
// word of the tail is word 0x201 (byte 0x804); the last is word 0x2ae: 174 words.
//
// The reserved area (window 0). The offset field of a chunk is 17 bits, so an area is at most 524288 bytes. The runtime places
// the DSP objects of run-time modules in it (docs/design/digikit-dkm.md, "DSP section"): the init data (code and data) and the
// zero-initialised bss of a module live in the area together.
#include "device-dt2.inc"
// A present position provider owns the last 16 words. R0/R4 are scratch at this check; the next instruction overwrites ASTAT.
// One declaration per line: patchkit's undeclared-symbol check reads `.EXTERN` at the start of a source line.
.EXTERN _pattern_position_info;
.EXTERN _instrument_reply;
.EXTERN _iv_lock_stage;
.EXTERN _phrase_control_info;
.EXTERN _phrase_reply;
#define DL_POSITION_EXTERN
// Transport reserves 16 position and 32 packet words; the optional lock
// receiver reserves another 18. Three words belong to each transfer header.
#define DL_POSITION_LIMIT R0 = _pattern_position_info; R4 = DL_TAIL_WORDS - 19; R0 = PASS R0; IF NE R3 = R4; R0 = _instrument_reply; R4 = DL_TAIL_WORDS - 51; R0 = PASS R0; IF NE R3 = R4; R0 = _iv_lock_stage; R4 = DL_TAIL_WORDS - 69; R0 = PASS R0; IF NE R3 = R4; R0 = _phrase_control_info; R4 = DL_TAIL_WORDS - 133; R0 = PASS R0; IF NE R3 = R4;
#define DL_LOOP_RETURN JUMP _dl_loop_status; _dl_loop_status_return: JUMP _dl_instrument_status; _dl_instrument_status_return: R0 = _phrase_reply; R0 = PASS R0; IF EQ JUMP _dl_no_phrase_reply; CALL _phrase_reply; _dl_no_phrase_reply:
#include "dsp-link.inc"
#include "loop-status.inc"
#include "instrument-status.inc"
.PKBSS _dl_area, DL_AREA_BYTES;
